import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a journal card 2 label as a textured plane with text and interactive effects.
 * @param {NodeConfig} config - Configuration object adhering to the node schema.
 * @param {NodeContext} ctx - Context with loaders, font atlas, and primitives.
 * @returns {THREE.Group} The constructed 3D object with event handlers and cleanup.
 */
export default function createNode(config, ctx) {
  const { scenePosition, sceneRotation, sceneScale, visual, textContent, behavior, cinematicPrimitives, assets } = config;
  const { ink, paper, accent, surface } = visual.colors;

  // --- Card plane ---
  const cardWidth = 1.2;
  const cardHeight = 0.75; // 512x320 aspect ratio
  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const texture = ctx.textureLoader.load(assets.imageUrl);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: paper, // fallback if texture missing
    transparent: true,
  });
  const card = new Mesh(geometry, material);
  card.position.set(0, 0, 0);

  // --- Text label ---
  const textNode = ctx.fontAtlas.createTextNode({
    text: textContent.text, // "Journal 2"
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.18, // ~39px at typical scene scale; adjust as needed
    color: ink,
    align: 'center',
    baseline: 'middle',
  });
  textNode.position.set(0, 0, 0.01); // slightly in front of card

  // --- Group ---
  const group = new Group();
  group.add(card);
  group.add(textNode);

  // Apply scene placement
  group.position.set(scenePosition[0], scenePosition[1], scenePosition[2]);
  group.rotation.set(sceneRotation[0], sceneRotation[1], sceneRotation[2]);
  group.scale.set(sceneScale[0], sceneScale[1], sceneScale[2]);

  // Store original position for hover reset
  const originalY = group.position.y;

  // GSAP tweens for hover and click
  let hoverTween = null;
  let clickTween = null;

  // --- Event handlers ---
  group.userData.handlers = {
    hover: (event) => {
      // Rise-in preset: subtle upward shift
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.5,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    hoverEnd: (event) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: originalY,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    click: (event) => {
      // Press-down animation
      if (clickTween) clickTween.kill();
      clickTween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.2,
            ease: 'power4.out',
          });
        },
      });
      // Emit navigation event
      group.dispatchEvent({ type: 'hub-journal.select', bubbles: true });
    },
  };

  // --- Cinematic primitives ---
  for (const primitive of cinematicPrimitives) {
    if (ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // --- Data binding (store slot reference for confirmPanel) ---
  group.userData.dataBindings = behavior.dataBindings.map(d => ({
    ...d,
    target: 'confirmPanel', // placeholder; actual binding managed externally
  }));

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (clickTween) clickTween.kill();
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // Dispose text node resources (if fontAtlas exposes cleanup)
    if (textNode.material) textNode.material.dispose();
    if (textNode.geometry) textNode.geometry.dispose();
  };

  return group;
}
